<div class="section-intro"><div><p class="eyebrow">ENTRÉES & SORTIES</p><h2>Enregistrer un mouvement</h2></div></div><section class="panel form-panel compact"><form method="post" action="<?= BASE_URL ?>/index.php?page=mouvement-save" class="data-form"><div class="form-grid three"><label>Type<select name="type_mouvement"><option value="ACHAT">Achat / entrée</option><option value="VENTE">Vente / sortie</option></select></label><label>Référence<select required name="produit_id"><?php foreach ($products as $product): ?><option value="<?= e($product['id']) ?>"><?= e($product['sku']) ?> · <?= e($product['nom']) ?> (<?= e($product['quantite']) ?>)</option><?php endforeach; ?></select></label><label>Quantité<input required type="number" min="1" step="1" name="quantite"></label></div><div class="form-grid three"><label>Prix unitaire achat<input required type="number" min="0" step="0.01" name="prix_unitaire" placeholder="Ignoré pour une vente"></label><label>Fournisseur / client<input name="tier_nom"></label><label>Mode de paiement<select name="mode_paiement"><option value="">Non précisé</option><option value="ESPECES">Espèces</option><option value="MOBILE_MONEY">Mobile money</option><option value="CARTE">Carte</option><option value="AUTRE">Autre</option></select></label></div><button class="button button-primary" type="submit">Enregistrer le mouvement</button></form></section><div class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">JOURNAL</p><h2>Historique des mouvements</h2></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Référence</th><th>Quantité</th><th>Prix unitaire</th><th>Total</th><th>Tiers</th></tr></thead><tbody><?php foreach ($movements as $movement): ?><tr><td><?= date('d/m/Y H:i', strtotime($movement['date_mouvement'])) ?></td><td><span class="type-label <?= strtolower($movement['type_mouvement']) ?>"><?= e($movement['type_mouvement']) ?></span></td><td><strong><?= e($movement['produit_nom'] ?? 'Référence supprimée') ?></strong><small><?= e($movement['sku'] ?? '—') ?></small></td><td><?= e($movement['quantite']) ?></td><td><?= money($movement['prix_unitaire']) ?></td><td><strong><?= money($movement['montant_total']) ?></strong></td><td><?= e($movement['tier_nom'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div></div>
